{
  "findings": [
    {
      "ref": "[R98]",
      "area": "skin",
      "claim": "A parent reports that imported skins revert to Steve after closing the app.",
      "stance": "risk",
      "quote": "I noticed all my skins are Steve. I always import skins and whenever I close the app they turn back into Steve!"
    },
    {
      "ref": "[R106]",
      "area": "skin",
      "claim": "A player reports that imported skins turn back into Steve after logging back in.",
      "stance": "risk",
      "quote": "whenever I import a skin, and go to put on a cape, it changed back to Alex, sometimes I even appear invisible because my friends can’t see my skin"
    },
    {
      "ref": "[R137]",
      "area": "skin",
      "claim": "A player reports that skins always load as a basic skin after loading in.",
      "stance": "risk",
      "quote": "for some reason every time i load in with a skin it just sets it to a basic skin"
    },
    {
      "ref": "[R155]",
      "area": "data",
      "claim": "A reviewer states that Microsoft took Minecraft out of China and wishes it would return.",
      "stance": "neutral",
      "quote": "please return to China"
    },
    {
      "ref": "[R123]",
      "area": "money",
      "claim": "A player reports that a purchased add-on was deleted and no Minecoins were refunded.",
      "stance": "risk",
      "quote": "I bought this morph add-on. I really don’t like it so I deleted it and it didn’t give me my mine coins back"
    },
    {
      "ref": "[R126]",
      "area": "money",
      "claim": "A reviewer reports being charged three times for the same add-on and not receiving the product.",
      "stance": "risk",
      "quote": "Attempted to buy add ons like I have in the past, it wasn’t working and after the third attempt for the same product, I was charged for buying the same add on 3 times."
    },
    {
      "ref": "[R147]",
      "area": "money",
      "claim": "A reviewer states that the game has a monthly charge that is not clearly communicated.",
      "stance": "risk",
      "quote": "I think it’s pretty scummy to not state up front that this is a monthly charge, not a one-and-done payment."
    },
    {
      "ref": "[R143]",
      "area": "bug",
      "claim": "A reviewer reports that their account keeps getting deleted and they are kicked out of the game with no updates.",
      "stance": "risk",
      "quote": "This is a really great game but there are a lot of bugs and it keeps deleting my account and it’s not letting me into the game at all it just keeps kicking me out no updates or anything"
    },
    {
      "ref": "[R149]",
      "area": "bug",
      "claim": "A reviewer reports that the game keeps kicking them out with a white screen after showing Moji.",
      "stance": "risk",
      "quote": "I’ve been trying to join Minecraft, but it keeps kicking me out. It shows Moji, and then it shows a white screen. It kicks me"
    },
    {
      "ref": "[R159]",
      "area": "bug",
      "claim": "A reviewer reports that all their coal disappears from their inventory after a few hours.",
      "stance": "risk",
      "quote": "My COAL DISAPPEARS! When I come to play again after a few hours, I notice that all my coal disappears from my items."
    },
    {
      "ref": "[R140]",
      "area": "content",
      "claim": "A reviewer reports that scary myths like Herobrine and entity 303 are still present and frightening.",
      "stance": "risk",
      "quote": "why is he still coming. You should add new stuff too like new mobs, forest, caves stuff like that. Also remove blood rain on Halloween it’s freaking me out lol and remove entity 303 too because he crashed my game"
    },
    {
      "ref": "[R161]",
      "area": "contact",
      "claim": "A reviewer states that signing in is required to play online and finds it weird.",
      "stance": "neutral",
      "quote": "Do not get why you have to sign in to play online and all that stuff like it’s weird overall game is super fun."
    },
    {
      "ref": "[R162]",
      "area": "contact",
      "claim": "A reviewer reports being locked out of their account and needing to use a parent's email to sign in.",
      "stance": "risk",
      "quote": "Gosh Minecraft NEVER have I EVER been so MAD in my life! ... as I put my email in it says account has been locked! So I used my mother’s email and it work but it was talking about some unusual activity"
    },
    {
      "ref": "[R122]",
      "area": "developer_record",
      "claim": "A reviewer reports that an add-on they purchased broke after signing in.",
      "stance": "risk",
      "quote": "I was just playing this game but when I saw 1 game that had 1 addon made the game I made broke. I sign in but is definitely not work."
    },
    {
      "ref": "[R123]",
      "area": "money",
      "claim": "A reviewer states that a purchased add-on did not give a refund after deletion.",
      "stance": "risk",
      "quote": "I bought this morph add-on. I really don’t like it so I deleted it and it didn’t give me my mine coins back"
    },
    {
      "ref": "[R144]",
      "area": "age_gating",
      "claim": "A reviewer reports that parental controls cannot be turned off even after trying everything.",
      "stance": "risk",
      "quote": "When my parents try to turn off parental controls it won't work. We tried everything but it refused to change."
    }
  ]
}
